import {createPages} from '/components/pages.mjs';
import {createMessageWindow} from '/components/message-window.mjs';
await document.fonts.ready;
const app=document.createElement('div');app.className='pot-app';document.body.append(app);
const scroller=document.createElement('div');scroller.className='history';scroller.style.cssText='height:650px;overflow:auto;width:850px;margin:20px auto;background:var(--panel,#fff)';
const column=document.createElement('div');column.className='message-column';const host=document.createElement('div'),approvals=document.createElement('section');approvals.className='chat-approvals';column.append(host,approvals);scroller.append(column);app.append(scroller);
const unavailable=document.createElement('div'),approvalHost=document.createElement('div');app.append(unavailable,approvalHost);
const scope={space:'synthetic-space',owner:'synthetic-owner'},notices=[],posts=[],decisions=[],events=[],frames=[];
const client={runtime:{boot_id:'synthetic-boot'},spaces:[{id:scope.space,control_id:'synthetic-control'}],assistants:[{id:scope.owner,space_id:scope.space,capabilities:{version:1,operations:['approvals.manage']}}],scope:()=>({...scope}),request:async(path,options={})=>{if(options.method==='POST')posts.push({at:performance.now(),path,body:options.body,scope:{...scope}});const response=await fetch(path,{method:options.method||'GET',headers:{'content-type':'application/json'},body:options.body?JSON.stringify(options.body):undefined,signal:options.signal});const value=await response.json();if(!response.ok)throw Error(value.message||'HTTP '+response.status);return value;}};
let rows=[{id:'body-D',viewKey:'body-D',text:'Initial stable body',revision:1}],windowUI,pages,phase='initial',clickOnReplay=false;
const ids=new WeakMap();let seq=0;const id=node=>{if(!node)return null;if(!ids.has(node))ids.set(node,++seq);return ids.get(node);};
function cardSample(node){return {id:id(node),connected:node.isConnected,approval:node.dataset.approvalId,text:node.querySelector('.approval-operation')?.textContent,state:node.querySelector('.approval-state')?.textContent,open:node.open,buttons:[...node.querySelectorAll('button')].map(b=>({id:id(b),disabled:b.disabled,text:b.textContent})),error:node.querySelector('[role=alert]')?.textContent};}
function sample(){return {at:performance.now(),phase,scope:{...scope},regionRevision:pages?.approvalRegion().revision,busy:host.getAttribute('aria-busy'),regionHidden:approvals.hidden,body:host.textContent,live:[...approvals.querySelectorAll('.approval-card')].map(cardSample),candidates:[...document.querySelectorAll('[data-preparation-surface]')].map(surface=>({surface:id(surface),inert:surface.inert||!!surface.closest('[inert]'),cards:[...surface.querySelectorAll('.approval-card')].map(cardSample),image:[...surface.querySelectorAll('img')].map(img=>({id:id(img),complete:img.complete,src:img.src}))})),posts:posts.length,decisions:decisions.length};}
function draw(){pages?.renderApprovals();windowUI?.setMessages(rows,{regions:[pages.approvalRegion()]});}
pages=createPages({client,host:unavailable,approvalHost,chatApprovalHost:approvals,chatVisible:()=>false,locale:()=> 'en',notify:value=>notices.push({at:performance.now(),value}),changed:()=>{},titleChanged:()=>{},openChat:()=>{},onApprovalsChanged:draw});
windowUI=createMessageWindow({scroller,host,render:(message,old)=>{const record=old||{row:document.createElement('article')};record.row.className='message assistant';if(record.signature!==JSON.stringify(message)){record.signature=JSON.stringify(message);record.row.replaceChildren();const p=document.createElement('p');p.textContent=message.text;record.row.append(p);if(message.held){const img=document.createElement('img');img.src='/held.png?key='+message.held;img.width=480;img.height=280;record.row.append(img);}}return record;},dispose:record=>record.row.remove(),requestRender:draw});
const observer=new MutationObserver(()=>{const s=sample();events.push({kind:'dom',...s});if(clickOnReplay&&s.phase.endsWith('release')&&s.live.some(card=>card.text?.endsWith('2')&&card.buttons.some(b=>!b.disabled))){clickOnReplay=false;const button=approvals.querySelector('button');events.push({kind:'synthetic-click',button:id(button),...sample()});button.click();queueMicrotask(()=>events.push({kind:'click-microtask',...sample()}));}});observer.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['disabled','hidden','aria-busy']});
let running=true;function tick(){if(!running)return;frames.push(sample());requestAnimationFrame(tick);}requestAnimationFrame(tick);
window.D={pages,windowUI,client,scope,posts,decisions,events,frames,notices,sample,draw,setPhase(value){phase=value;events.push({kind:'phase',...sample()});},async control(body){return fetch('/fixture/control',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json());},async start(){await pages.permissions();draw();},async slow(key,revision){rows=[{id:'body-D',viewKey:'body-D',text:'Held body '+key,held:key,revision}];await this.control({mode:'fresh',revision});await pages.permissions();draw();},async stale(){await this.control({mode:'stale'});await pages.permissions();draw();},clear(){pages.clearApprovals();},arm(){clickOnReplay=true;},click(){const button=approvals.querySelector('button');events.push({kind:'synthetic-click',button:id(button),...sample()});button?.click();},stop(){running=false;observer.disconnect();pages.dispose();windowUI.close();}};
await D.start();
const run=document.createElement('button');run.textContent='Run approval generation D';run.id='run-D';app.prepend(run);const result=document.createElement('pre');result.style.cssText='display:none';result.id='result-D';app.append(result);
const wait=async(predicate,label)=>{const start=performance.now();while(!predicate()){if(performance.now()-start>4000)throw Error('Timeout: '+label);await new Promise(requestAnimationFrame);}};
run.onclick=async()=>{run.disabled=true;let failure;const checkpoints=[];const capture=label=>{const value={label,...sample()};checkpoints.push(value);return value;};try{
await wait(()=>!host.hasAttribute('aria-busy')&&approvals.querySelector('.approval-card'),'initial commit');approvals.querySelector('.approval-card').open=true;capture('fresh initial');
D.setPhase('stale-held');await D.slow('D-stale',2);await wait(()=>host.hasAttribute('aria-busy')&&[...document.querySelectorAll('[data-preparation-surface] img')].some(img=>!img.complete)&&[...document.querySelectorAll('[data-preparation-surface] .approval-operation')].some(n=>n.textContent.endsWith('2')),'held stale candidate');capture('fresh revision 2 candidate held');
await D.stale();capture('stale current while candidate held');D.arm();D.setPhase('stale-release');await D.control({release:'D-stale'});
await wait(()=>!host.hasAttribute('aria-busy')&&approvals.querySelector('button')?.disabled,'stale final disabled');capture('stale settled');
const replay=events.find(e=>e.kind==='synthetic-click'&&e.phase==='stale-release');if(replay)throw Error('Old fresh approval was replayed after stale');if(frames.some(f=>f.phase==='stale-release'&&f.live.some(c=>c.buttons.some(b=>!b.disabled))))throw Error('Enabled stale approval published');
D.setPhase('clear-held');await D.slow('D-clear',3);await wait(()=>host.hasAttribute('aria-busy')&&[...document.querySelectorAll('[data-preparation-surface] img')].some(img=>!img.complete)&&[...document.querySelectorAll('[data-preparation-surface] .approval-operation')].some(n=>n.textContent.endsWith('3')),'held clear candidate');capture('fresh revision 3 candidate held');
D.clear();capture('current cleared without new batch');D.setPhase('clear-release');await D.control({release:'D-clear'});
await wait(()=>!host.hasAttribute('aria-busy')&&!approvals.querySelector('.approval-card'),'cleared region commit');capture('cleared region committed');D.click();await new Promise(queueMicrotask);await new Promise(requestAnimationFrame);capture('cleared old click rejected');
// Observe every frame through both releases, including the intermediate live state.
if(posts.length)throw Error('Unexpected decision POST');if(frames.some(f=>f.phase==='clear-release'&&f.live.some(c=>c.buttons.some(b=>!b.disabled))))throw Error('Cleared enabled approval published');
}catch(e){failure=e.stack;}
const payload={failure,checkpoints,events,frames,notices,posts,decisions,final:sample()};await fetch('/fixture/evidence',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});result.textContent=JSON.stringify({failure,checkpoints:checkpoints.map(({label,at,busy,live})=>({label,at,busy,live})),posts:posts.length},null,2);};
